/* harmony default export */ __webpack_exports__["default"] = ({
  onReady() {
    this.$refs.uForm.setRules(this.rules);
  },
  data() {
    return {
      labelPosition: 'left',
      border: false,
      radioCheckWidth: 'auto',
      radioCheckWrap: false,
      form: {
        account: '',
        newpassword: '',
        type: 'email',
        captcha: ''
      },
      rules: {
        account: [{
          validator: (rule, value, callback) => {
            rule.message = `请填写${this.form.type == 'email' ? '邮箱' : '手机号码'}`;
            return !!value;
          },
          message: '',
          trigger: 'blur'
        }],
        newpassword: [{
          required: true,
          message: '请输入新密码',
          trigger: 'blur'
        }],
        captcha: [{
          required: true,
          message: '请输入验证码',
          trigger: 'blur'
        }]
      },
      codeTips: '',
      errorType: ['message']
    };
  },
  methods: {
    codeChange(text) {
      this.codeTips = text;
    },
    radioGroupChange(e) {
      this.form.type = e;
    },
    // 获取验证码
    getCode: async function (type) {
      if (this.$refs.uCode.canGetCode) {
        let res = {};
        if (this.form.type == 'email') {
          if (!this.$u.test.email(this.form.account)) {
            this.$u.toast('邮箱格式不正确！');
            return;
          }
          res = await this.$api.getEmsSend({
            email: this.form.account,
            event: 'resetpwd'
          });
        } else {
          if (!this.$u.test.mobile(this.form.account)) {
            this.$u.toast('手机号码格式不正确！');
            return;
          }
          res = await this.$api.getSmsSend({
            mobile: this.form.account,
            event: 'resetpwd'
          });
        }
        setTimeout(() => {
          this.$u.toast(res.msg || '发送失败');
        }, 50);
        if (res.code == 1) {
          this.$refs.uCode.start();
        }
      } else {
        this.$u.toast('倒计时结束后再发送');
      }
    },
    submit() {
      this.$refs.uForm.validate(async valid => {
        if (valid) {
          let res = await this.$api.goResetpwd({
            type: this.form.type,
            mobile: this.form.account,
            email: this.form.account,
            newpassword: this.form.newpassword,
            captcha: this.form.captcha
          });
          if (!res.code) {
            this.$u.toast(res.msg);
            return;
          }
          setTimeout(() => {
            this.$u.route({
              url: '/pages/login/login',
              type: 'redirect'
            });
          }, 800);
        } else {
          this.$u.toast('验证失败');
        }
      });
    }
  }
});

